let editingIssue=null,editingEntry=null,entryIssue=null;
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'});
issues.forEach(i=>{i.entries??=[];i.status??='觀察中';i.then??=''});
const safeLink=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
window.renderIssueManager=function(){
 const opened=new Set([...document.querySelectorAll('[data-open][open]')].map(x=>x.dataset.open));
 $('#issues').innerHTML=issues.map(i=>{const linked=videos.filter(v=>matches(v,i));return `<details class="issue issue-compact" data-open="card:${esc(i.id)}" ${opened.has('card:'+i.id)?'open':''}><summary class="issue-summary"><span class="issue-title">${esc(i.name)}</span><span class="issue-status">${esc(i.status)}</span><span class="issue-meta">${i.entries.length} 筆記事 · ${linked.length} 部相關影片</span></summary><div class="issue-expanded"><p>${esc(i.keys.join(' · '))}</p><div class="issue-actions"><button data-edit="${esc(i.id)}">✎ 編輯議題</button><button data-entry="${esc(i.id)}">＋ 記事／連結</button></div><div class="issue-content"><div class="judgment-compare"><div><div class="judgment-label">當時</div><p>${esc(i.then||'尚未填寫')}</p></div><div><div class="judgment-label">現在</div><p>${esc(i.note||'尚未填寫')}</p></div></div><h4>我的記事</h4><ol class="timeline">${i.entries.map((e,index)=>({...e,index})).sort((a,b)=>b.date.localeCompare(a.date)||b.index-a.index).map(e=>`<li><div class="timeline-head"><time>${esc(e.date)}</time><span>${esc(e.label)}</span><button data-edit-entry="${esc(e.id)}" data-owner="${esc(i.id)}">✎ 編輯</button><button data-remove-entry="${esc(e.id)}" data-owner="${esc(i.id)}" aria-label="刪除記事">♲</button></div><p>${esc(e.text)}</p>${(e.links||[]).filter(l=>safeLink(l.url)).map(l=>`<a class="source-link" href="${esc(safeLink(l.url))}" target="_blank" rel="noopener">↗ ${esc(l.title)}</a>`).join('')}</li>`).join('')||'<p class="muted">還沒有記事，按「＋ 記事／連結」新增。</p>'}</ol><h4>相關段落</h4><ul class="related-chapters">${linked.flatMap(v=>chapters(v).filter(c=>chapterMatches(c.title,chapterTerms(i))).map(c=>`<li><a href="${esc(c.url)}" target="_blank" rel="noopener"><span class="related-chapter-meta">${date(v.published)} · ${esc(c.time)}</span><span>${esc(c.title)}</span></a></li>`)).join('')||'<li>尚無符合關鍵字的段落</li>'}</ul></div><div class="links"><button data-filter="${esc(i.id)}">查看相關影片 →</button> <button data-delete="${esc(i.id)}">刪除議題</button></div></div></details>`}).join('');
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openIssueEditor(b.dataset.edit));
 document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>openEntry(b.dataset.entry));
 document.querySelectorAll('[data-edit-entry]').forEach(b=>b.onclick=()=>openEntry(b.dataset.owner,b.dataset.editEntry));
 document.querySelectorAll('[data-remove-entry]').forEach(b=>b.onclick=()=>{if(confirm('確定刪除此篇記事？')){let i=issues.find(i=>i.id===b.dataset.owner);i.entries=i.entries.filter(e=>e.id!==b.dataset.removeEntry);save();renderIssues()}});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{selected=issues.find(i=>i.id===b.dataset.filter);category='全部';limit=10;renderTabs();renderNews()});
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('確定刪除此議題及其記事？')){issues=issues.filter(i=>i.id!==b.dataset.delete);if(selected?.id===b.dataset.delete)selected=null;save();renderIssues();renderNews()}});
};
function openIssueEditor(id){editingIssue=id||null;$('#keyword-message').textContent='';const i=issues.find(i=>i.id===id);$('#editor-title').textContent=i?'編輯議題':'新增追蹤議題';$('#issue-name').value=i?.name||'';$('#issue-keys').value=i?.keys.join(', ')||'';$('#issue-status').value=i?.status||'觀察中';$('#issue-then').value=i?.then||'';$('#issue-note').value=i?.note||'';$('#editor').showModal()}
function saveIssueForm(e){e.preventDefault();let name=$('#issue-name').value.trim();if(!name)return;let keys=$('#issue-keys').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(!keys.length)return;let i=issues.find(i=>i.id===editingIssue);if(!i){i={id:crypto.randomUUID(),entries:[]};issues.push(i)}Object.assign(i,{name,keys,status:$('#issue-status').value,then:$('#issue-then').value,note:$('#issue-note').value});save();renderIssues();renderNews();$('#editor').close()}
function openEntry(id,eid){entryIssue=id;editingEntry=eid||null;const e=issues.find(i=>i.id===id).entries.find(e=>e.id===eid);renderEntryIssues(eid?issues.filter(i=>i.entries.some(x=>x.id===eid)).map(i=>i.id):[id]);$('#entry-title').textContent=e?'編輯記事':'新增記事';$('#entry-date').value=e?.date||today();$('#entry-label').value=e?.label||'筆記';$('#entry-text').value=e?.text||'';$('#entry-links').value=(e?.links||[]).map(l=>`${l.title} | ${l.url}`).join('\n');$('#entry-error').textContent='';$('#entry-videos').innerHTML=videos.map(v=>`<div class="attachment-video"><label class="video-choice"><input type="checkbox" data-url="${esc(v.url)}" data-title="${esc(v.title)}">${esc(v.title)}</label>${chapters(v).length?`<details><summary>選擇章節（${chapters(v).length}）</summary>${chapters(v).map(c=>`<label class="video-choice chapter-choice"><input type="checkbox" data-url="${esc(c.url)}" data-title="${esc(v.title+'｜'+c.time+' '+c.title)}"><span><b>${esc(c.time)}</b> ${esc(c.title)} <a href="${esc(c.url)}" target="_blank" rel="noopener">播放 ↗</a></span></label>`).join('')}</details>`:''}</div>`).join('');$('#entry-editor').showModal()}
$('#entry-cancel').onclick=()=>$('#entry-editor').close();
$('#entry-form').onsubmit=e=>{e.preventDefault();let links=[];for(const row of $('#entry-links').value.split('\n').filter(s=>s.trim())){const pos=row.indexOf('|'),url=(pos<0?row:row.slice(pos+1)).trim(),title=pos<0?url:row.slice(0,pos).trim();const valid=safeLink(url);if(!valid){$('#entry-error').textContent='連結請使用有效的 http 或 https 網址。';return}links.push({title:title||url,url:valid})}document.querySelectorAll('#entry-videos input:checked').forEach(c=>{const url=c.dataset.url,title=c.dataset.title;if(!links.some(l=>l.url===url))links.push({title,url})});const ids=[...document.querySelectorAll('#entry-issues input:checked')].map(c=>c.value);if(!ids.length){$('#entry-error').textContent='請至少勾選一個關聯議題';return}const item={id:editingEntry||crypto.randomUUID(),date:$('#entry-date').value,label:$('#entry-label').value,text:$('#entry-text').value,links,issueIds:ids};applyEntryToIssues(issues,item,ids);entryIssue=ids[0];save();$('#entry-editor').close();renderIssues();const detail=[...document.querySelectorAll('[data-open]')].find(d=>d.dataset.open==='card:'+entryIssue);if(detail)detail.open=true};
renderIssues();load();

$('#suggest-keywords').onclick=()=>{const title=$('#issue-name').value.trim();if(!title){$('#keyword-message').textContent='請先填寫議題名稱';$('#issue-name').focus();return}const words=suggestKeywords(title);if(!words.length){$('#keyword-message').textContent='未找到適合詞彙，請自行填寫關鍵字';return}const current=$('#issue-keys').value.trim();if(current&&!confirm('要以建議關鍵字取代目前內容嗎？'))return;$('#issue-keys').value=words.join(', ');$('#keyword-message').textContent='已產生 '+words.length+' 個關鍵字，可自行修改（詞彙規則，非 AI）'};

window.bindChapterNotes=function(){document.querySelectorAll('[data-chapter-note]').forEach(button=>button.onclick=()=>{
 if(!issues.length){openIssueEditor();return}
 const video=videos.find(v=>v.id===button.dataset.chapterNote),chapter=chapters(video).find(c=>c.seconds===Number(button.dataset.seconds));if(!chapter)return;
 const related=issues.filter(i=>chapterMatches(chapter.title,chapterTerms(i))),first=selected||related[0]||issues[0];
 openEntry(first.id);renderEntryIssues([first.id],related.map(i=>i.id));
 $('#entry-links').value=video.title+'｜'+chapter.time+' '+chapter.title+' | '+chapter.url;

 })};

function renderEntryIssues(ids,related=[]){$('#entry-issues').innerHTML=issues.map(i=>`<label class="video-choice"><input type="checkbox" value="${esc(i.id)}" ${ids.includes(i.id)?'checked':''}><span>${esc(i.name)}${related.includes(i.id)?'（符合章節）':''}</span></label>`).join('')}
